import { colors as palette } from '@/styles/tokens';
import * as tokens from './styles/tokens';
const CONFIG = { ongoing: { color: palette.live } };
export function Badge({status}: {status: keyof typeof CONFIG}) {
 const cfg = CONFIG[status];
 return <span style={{ color: cfg.color }}>LIVE<i style={{ background: cfg.color }} /><b style={{backgroundColor: tokens.colors.live}} /></span>;
}

